    get showsSecondaryEdit() {
      return (this.primaryAction === 'task' || this.primaryAction === 'action') && this.canEdit && !this.isNarrow;
    },

    get editInMenu() {
      return (this.primaryAction === 'task' || this.primaryAction === 'action') && this.canEdit && this.isNarrow;
    },

    // The overflow menu renders only when it would carry something.
    // What the overflow menu would actually carry. Asked here rather than guessed in the markup, so
    // the trigger can hide when the menu would open empty and a group separator can render only when
    // there is a group above it to separate. Both of those regressed the moment the one entry that
    // used to be unconditional went away.
    get menuHasPrint() {
      return false;
    },

    get menuHasCalendars() {
      return false;
    },

    get menuHasDelete() {
      return this.canEdit;
    },

    // The record's own contributed actions, for the overflow menu (#8116): the list sheet's rule
